    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    # Join 1-markers sharing a diagonal; retain any original 6 marker on the line.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2-r1, c2-c1
            if abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                for k in range(abs(dr) + 1):
                    rr, cc = r1 + sr*k, c1 + sc*k
                    if grid[rr][cc] != 6:
                        out[rr][cc] = 1
    # Extend each 6 marker's diagonal through the grid in both directions.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 6:
                for sr, sc in ((1, 1), (1, -1)):
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == 4:
                            out[rr][cc] = 6
                        rr += sr
                        cc += sc
                    rr, cc = r-sr, c-sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == 4:
                            out[rr][cc] = 6
                        rr -= sr
                        cc -= sc
    return out
