    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    sixes = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]

    # Connect the two 1 markers with a 45-degree segment when aligned.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc):
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                for k in range(abs(dr) + 1):
                    rr, cc = r1 + sr * k, c1 + sc * k
                    if grid[rr][cc] != 6:
                        out[rr][cc] = 1
                # The 6 markers on this diagonal continue on the perpendicular diagonal.
                for r, c in sixes:
                    if abs(r-r1) == abs(c-c1) and (r-r1)*dr >= 0 and (c-c1)*dc >= 0:
